// Website jawab se ===HTML=== / ===CSS=== / ===JS=== sections nikaalo (Claude v5 jaisa).
function webPart(t, a, b) {
  var i = t.indexOf(a);
  if (i < 0) return null;
  i += a.length;
  var j = b ? t.indexOf(b, i) : -1;
  var r = j < 0 ? t.slice(i) : t.slice(i, j);
  return r.replace(/^\s*```[a-z]*\s*/i, "").replace(/\s*```\s*$/, "").trim();
}
