var COLOURS = {neela:"blue",laal:"red",lal:"red",safed:"white",kala:"black",kaala:"black",hara:"green",peela:"yellow",gulabi:"pink",narangi:"orange",bhura:"brown",bhoora:"brown"};
function tokenize(s) {
  return String(s || "").toLowerCase().split(/[^a-z0-9\u0900-\u097f]+/).filter(Boolean).map(function (t) { return COLOURS[t] || t; });
}
function tokenHit(toks, q) {
  if (toks.has(q)) return true;
  if (q.length < 4) return false;
  var hit = false;
  toks.forEach(function (tk) { if (!hit && tk.length >= 4 && (tk.indexOf(q) === 0 || q.indexOf(tk) === 0)) hit = true; });
  return hit;
}
function productTokens(p) {
  return new Set(tokenize(p[0] + " " + p[3] + " " + p[2]));
}
// Module load par har product ke tokens ek baar banao (har request par nahi).
var CAT_TOKENS = CATALOG.map(function (p) { return { item: p, toks: productTokens(p) }; });
var FEAT_TOKENS = FEATURED.map(function (p) { return { item: p, toks: productTokens(p) }; });
function scoreOne(item, toks, qtoks, featured) {
  var s = 0;
  for (var i = 0; i < qtoks.length; i++) {
    var q = qtoks[i];
    if (/^\d+$/.test(q)) { if (item[1] === Number(q)) s += 6; continue; }
    if (toks.has(q)) s += 2;
    else if (tokenHit(toks, q)) s += 1;
  }
  if (featured && s > 0) s += 3; // bonus sirf tab jab token/price se match ho
  return s;
}
// User ke aakhri message se dukaan ke sabse achhe matches nikalo (zyada se zyada `limit`).
function matchProducts(text, limit) {
  var qtoks = tokenize(text).filter(function (t) { return !STOP_WORDS[t]; });
  if (!qtoks.length) return [];
  var nums = qtoks.filter(function (t) { return /^\d+$/.test(t); }).map(Number);
  var under = null;
  if (nums.length) {
    for (var i = 0; i < qtoks.length; i++) {
      if (qtoks[i] === "under" || qtoks[i] === "andar" || qtoks[i] === "niche" || qtoks[i] === "kam") { under = nums[0]; break; }
    }
  }
  var cheap = qtoks.indexOf("sasta") !== -1 || qtoks.indexOf("saste") !== -1 || qtoks.indexOf("sasti") !== -1 || qtoks.indexOf("cheap") !== -1 || qtoks.indexOf("cheapest") !== -1;
  var costly = qtoks.indexOf("mehenga") !== -1 || qtoks.indexOf("mehnga") !== -1 || qtoks.indexOf("mahanga") !== -1 || qtoks.indexOf("mahange") !== -1 || qtoks.indexOf("expensive") !== -1;
  // Content tokens: number/signal shabd nahi. Jo token kisi bhi product mein
  // kahin milta hi nahi (jaise "kurta", "size") use zaroori list mein mat rakho —
  // usse match khali nahi hoga, model system prompt se jawab dega.
  var SIGNALS = {sasta:1, saste:1, sasti:1, cheap:1, cheapest:1, mehenga:1, mehnga:1, mahanga:1, mahange:1, expensive:1, under:1, andar:1, niche:1, kam:1};
  var content = qtoks.filter(function (t) { return !/^\d+$/.test(t) && !SIGNALS[t]; });
  var required = content.filter(function (q) {
    for (var i = 0; i < CAT_TOKENS.length; i++) if (tokenHit(CAT_TOKENS[i].toks, q)) return true;
    for (var j = 0; j < FEAT_TOKENS.length; j++) if (tokenHit(FEAT_TOKENS[j].toks, q)) return true;
    return false;
  });
  var scored = [];
  function consider(entry, featured) {
    if (under !== null && entry.item[1] > under) return;
    for (var r = 0; r < required.length; r++) if (!tokenHit(entry.toks, required[r])) return;
    var s = scoreOne(entry.item, entry.toks, qtoks, featured);
    if (s > 0) scored.push({ item: entry.item, score: s, featured: featured });
  }
  FEAT_TOKENS.forEach(function (e) { consider(e, true); });
  CAT_TOKENS.forEach(function (e) { consider(e, false); });
  scored.sort(function (a, b) {
    // Sasta/mehenga poochha ho to price pehle (score sirf filter ka kaam karta hai).
    if (cheap) { if (a.item[1] !== b.item[1]) return a.item[1] - b.item[1]; }
    if (costly) { if (a.item[1] !== b.item[1]) return b.item[1] - a.item[1]; }
    if (b.score !== a.score) return b.score - a.score;
    if (a.featured !== b.featured) return a.featured ? -1 : 1;
    if (cheap) return a.item[1] - b.item[1];
    if (costly) return b.item[1] - a.item[1];
    return a.item[1] - b.item[1];
  });
  return scored.slice(0, limit).map(function (r) {
    return { name: r.item[0], price: r.item[1], category: r.item[2], brand: r.item[3], featured: r.featured };
  });
}

function json(res, status, obj) {
  res.statusCode = status;
  res.setHeader("Content-Type", "application/json; charset=utf-8");
  res.setHeader("Cache-Control", "no-store");
  res.end(JSON.stringify(obj));
}

// Client ke messages ko Gemini ke format mein badlo:
// role user -> "user", assistant -> "model"; lagataar ek hi role ko jod do;
// pehla message user ka hona chahiye; aakhri 12 turns hi rakho.
function cleanMessages(input) {
  if (!Array.isArray(input)) return null;
  var out = [];
  for (var i = 0; i < input.length; i++) {
    var m = input[i];
    if (!m || typeof m.text !== "string") continue;
    var text = m.text.trim();
    if (!text) continue;
    if (text.length > MAX_TEXT) text = text.slice(0, MAX_TEXT);
    var role = m.role === "assistant" ? "model" : "user";
    if (out.length && out[out.length - 1].role === role) {
      out[out.length - 1].parts[0].text += "\n" + text;
    } else {
      out.push({ role: role, parts: [{ text: text }] });
    }
  }
  // Aakhri 12 turns hi rakho — kaatne ke baad bhi pehla message user ka hona
  // chahiye (Gemini user se shuru na ho to 400 deta hai).
  out = out.slice(-MAX_TURNS * 2);
  while (out.length && out[0].role !== "user") out.shift();
  if (!out.length) return null;
  return out;
}

// ---- Live web search (Serper.dev Google Search API, key SERPER_API_KEY se) ----
// Sawal aaj ki jaankari maange (bhav, news, mausam...) to Google se taza results
// nikaal kar Gemini ko dete hain, taaki jawab aaj ka ho. Key na ho ya search
// fail ho to khaali list — chat kabhi nahi rukta. (DuckDuckGo block hai, isliye
// Serper use hota hai — 2,500 free queries, bina card.)
var LIVE_WORDS = ["aaj", "आज", "today", "abhi", "अभी", "current", "latest", "live", "taza", "ताज़ा", "fresh", "price", "bhav", "भाव", "rate", "daam", "दाम", "kimat", "कीमत", "sona", "gold", "chandi", "silver", "bitcoin", "crypto", "petrol", "diesel", "stock", "share", "sensex", "nifty", "dollar", "rupee", "news", "khabar", "खबर", "mausam", "मौसम", "weather", "barish", "बारिश", "temperature", "match", "cricket", "score"];
function needsLiveInfo(text) {
  if (!text) return false;
  var low = String(text).toLowerCase();
  for (var i = 0; i < LIVE_WORDS.length; i++) {
    if (low.indexOf(LIVE_WORDS[i].toLowerCase()) >= 0) return true;
  }
  return false;
}
async function webSearch(query) {
  var out = [];
  var key = process.env.SERPER_API_KEY;
  if (!key || !String(key).trim()) return out;
  try {
    var r = await fetch("https://google.serper.dev/search", {
      method: "POST",
      headers: { "X-API-KEY": String(key).trim(), "Content-Type": "application/json" },
      body: JSON.stringify({ q: String(query).slice(0, 200), gl: "in", hl: "en", num: 5 }),
      signal: AbortSignal.timeout(3000)
    });
    if (!r || !r.ok) return out;
    var d = null;
    try { d = await r.json(); } catch (e) { return out; }
    if (!d || typeof d !== "object") return out;
    // answerBox (seedha jawab) sabse pehle — bhav/rate jaise sawalon ke liye.
    if (d.answerBox) {
      var ab = d.answerBox;
      var aText = ab.answer || ab.snippet || ab.title || "";
      if (aText) out.push({ title: "Seedha jawab", snippet: String(aText).slice(0, 220) });
    }
    var org = Array.isArray(d.organic) ? d.organic : [];
    for (var i = 0; i < org.length && out.length < 5; i++) {
      var o = org[i] || {};
      if (!o.title) continue;
      out.push({ title: String(o.title).slice(0, 120), snippet: String(o.snippet || "").slice(0, 220) });
    }
  } catch (e) { return []; }
  return out;
}

module.exports = async function (req, res) {
  var t0 = Date.now(); // continuation ke liye time budget napne ke liye
  if (req.method !== "POST") {
    res.setHeader("Allow", "POST");
    return json(res, 405, { error: "Sirf POST chalega." });
  }

  var key = process.env.GEMINI_API_KEY;
  if (!key || !String(key).trim()) {
    return json(res, 503, { error: "AI abhi set nahi hua hai. Server par key lagana baaki hai." });
  }

  var body = req.body;
  if (typeof body === "string") {
    try { body = JSON.parse(body); } catch (e) { body = null; }
  }
  // mode "image": sirf aakhri user prompt se ek SVG illustration banao.
  // Tasveer ke liye history nahi bhejte aur zyada tokens dete hain.
  // body.mode "image" = tasveer; baaki sab chat mode (aam/padhai/coding/...).
  var reqMode = body && typeof body.mode === "string" ? body.mode : "";
  var mode = reqMode === "image" ? "image" : "chat";
  var chatMode = SYS_MODES[reqMode] ? reqMode : "aam";
  var contents, sysText, maxTokens;
  // app quiz/flashcards: sirf topic se JSON sawal/card banao. History nahi,
  // photo nahi, dukaan match nahi, mode field ignore hota hai.
  var app = body && typeof body.app === "string" ? body.app : "";
  if (app) {
    if (app !== "quiz" && app !== "flashcards" && app !== "comic" && app !== "mindmap" && app !== "website") {
      return json(res, 400, { error: "Ye wala kaam nahi hota. Dobara try karo." });
    }
    var topic = "";
    if (body && Array.isArray(body.messages)) {
      for (var i = body.messages.length - 1; i >= 0; i--) {
        var tm = body.messages[i];
        if (tm && tm.role === "user" && typeof tm.text === "string" && tm.text.trim()) { topic = tm.text.trim(); break; }
      }
    }
    if (!topic) {
      return json(res, 400, { error: "Pehle topic likho." });
    }
    if (app === "website") {
      // Website: sirf user ki maang, history nahi, dukaan match nahi, photo nahi.
      contents = [{ role: "user", parts: [{ text: "User ki maang: " + topic.slice(0, MAX_TEXT) }] }];
      sysText = SYS_WEBSITE;
      // Edit: maujooda code bhi prompt mein do, poora updated code wapas aaye.
      var oldSite = body && body.website && typeof body.website === "object" ? body.website : null;
      if (oldSite && typeof oldSite.html === "string" && typeof oldSite.css === "string" && typeof oldSite.js === "string") {
        sysText += "\n\nYeh maujooda code hai, isi mein user ke kehne ke hisaab se badlav karo. Poora updated code wapas do, sirf badla hua hissa nahi:\n===HTML===\n" + oldSite.html.slice(0, 4000) + "\n===CSS===\n" + oldSite.css.slice(0, 4000) + "\n===JS===\n" + oldSite.js.slice(0, 4000);
      }
      maxTokens = 8192;
    } else {
      contents = [{ role: "user", parts: [{ text: "Topic: " + topic.slice(0, MAX_TEXT) }] }];
      sysText = app === "quiz" ? SYS_QUIZAPP : app === "flashcards" ? SYS_FLASH : app === "comic" ? SYS_COMIC : SYS_MINDMAP;
      maxTokens = 2048;
    }
  } else if (mode === "image") {
    var lastUser = "";
    if (body && Array.isArray(body.messages)) {
      for (var i = body.messages.length - 1; i >= 0; i--) {
        var mm = body.messages[i];
        if (mm && mm.role === "user" && typeof mm.text === "string" && mm.text.trim()) { lastUser = mm.text.trim(); break; }
      }
    }
    if (!lastUser) {
      return json(res, 400, { error: "Pehle likho ki kaisi tasveer chahiye." });
    }
    contents = [{ role: "user", parts: [{ text: "Tasveer: " + lastUser.slice(0, MAX_TEXT) }] }];
    sysText = SYS_IMG;
    maxTokens = 4096;
  } else {
    // Photo (agar bheji ho) pehle check karo — galat photo par turant 400.
    // Photo sirf is wale message ke saath Gemini ko jaati hai, history mein nahi.
    var img = null;
    if (body && body.image != null) {
      img = parseImage(body.image);
      if (img.error) {
        return json(res, 400, { error: img.error });
      }
    }
    contents = body ? cleanMessages(body.messages) : null;
    if (!contents || !contents.length) {
      if (img) {
        contents = [{ role: "user", parts: [{ text: DEFAULT_PHOTO_Q }] }];
      } else {
        return json(res, 400, { error: "Kuch likh kar bhejo, phir jawab milega." });
      }
    }
    if (contents[contents.length - 1].role !== "user") {
      return json(res, 400, { error: "Aakhri message tumhara hona chahiye." });
    }
    if (img) {
      contents[contents.length - 1].parts.push({ inlineData: { mimeType: img.mime, data: img.data } });
    }
    var lastText = contents[contents.length - 1].parts[0].text;
    var matches = matchProducts(lastText, 8);
    sysText = SYS + SYS_SHOP + SYS_CONNECT;
    if (SYS_MODES[chatMode]) sysText += "\n\n" + SYS_MODES[chatMode];
    if (matches.length) {
      sysText += "\n\nDukaan ke products (is sawal se match karte hain):\n" + matches.map(function (m) {
        return "- " + m.name + " — ₹" + m.price + " (" + m.category + ", " + m.brand + ")";
      }).join("\n");
    }
    // Live info: sawal aaj ki jaankari (bhav, news, mausam...) maange to web se
    // taza results Gemini ko do — taaki jawab aaj ka ho, purana nahi.
    var liveCount = 0;
    if (needsLiveInfo(lastText)) {
      var live = await webSearch(lastText);
      if (live.length) {
        liveCount = live.length;
        sysText += "\n\nWeb se mili taza jaankari (aaj ki khabar/bhav — inhi ko use karke jawab do; agar inmein jawab na mile to imaandaari se bolo ki taza jaankari nahi mili):\n" + live.map(function (w, i) {
          return (i + 1) + ". " + w.title + (w.snippet ? " — " + w.snippet : "");
        }).join("\n");
      }
    }
    maxTokens = liveCount ? 1536 : 1024;
  }

  var url = "https://generativelanguage.googleapis.com/v1beta/models/" + MODEL + ":generateContent?key=" + encodeURIComponent(String(key).trim());
  var payload = {
    systemInstruction: { parts: [{ text: sysText }] },
    contents: contents,
    generationConfig: { temperature: 0.7, maxOutputTokens: maxTokens }
  };

  var upstream;
  try {
    upstream = await fetch(url, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(payload),
      signal: AbortSignal.timeout(FETCH_TIMEOUT_MS)
    });
  } catch (e) {
    return json(res, 504, { error: "Gemini se jod nahi paya. Thodi der baad dobara try karo." });
  }

  if (upstream.status === 429) {
    return json(res, 429, { error: "Free limit poori ho gayi hai. Thodi der ruk kar dobara try karo." });
  }
  if (!upstream.ok) {
    // Key ya setting ki gadbad (400/403) ya Gemini ki taraf se error.
    // Gemini ka raw error wapas nahi bhejte — usmein kabhi key ka hissa na aaye, isiliye sirf status dekhte hain.
    if (upstream.status === 400 || upstream.status === 403) {
      return json(res, 502, { error: "AI key ya setting mein gadbad hai. Key check karke dobara lagao." });
    }
    return json(res, 502, { error: "Gemini se jawab nahi mila. Thodi der baad dobara try karo." });
  }

  var data = null;
  try { data = await upstream.json(); } catch (e) { data = null; }
  var reply = "";
  try {
    var parts = data && data.candidates && data.candidates[0] && data.candidates[0].content && data.candidates[0].content.parts;
    if (Array.isArray(parts)) {
      reply = parts.map(function (p) { return p && typeof p.text === "string" ? p.text : ""; }).join("").trim();
    }
  } catch (e) { reply = ""; }
  if (!reply) {
    return json(res, 502, { error: "Gemini ne khali jawab diya. Dobara try karo." });
  }
  var finishReason = "";
  try { finishReason = (data && data.candidates && data.candidates[0] && data.candidates[0].finishReason) || ""; } catch (e) { finishReason = ""; }
  // Website: agar code beech mein kat gaya (MAX_TOKENS), ek baar aage continue karwao.
  // Sirf tab jab time bacha ho (Vercel 10s limit) — warna partial reply hi rahega.
  if (app === "website" && finishReason === "MAX_TOKENS" && (Date.now() - t0) < 5000) {
    try {
      var contContents = [
        { role: "user", parts: [{ text: "User ki maang: " + topic.slice(0, MAX_TEXT) }] },
        { role: "model", parts: [{ text: reply }] },
        { role: "user", parts: [{ text: "Aage continue karo, wahi se jahan ruka tha. Dobara shuru se mat likho. Jo section beech mein ruka tha, usi ko aage badhao — uska heading dobara mat likho. Jab ek section poora ho jaye to agle section ka heading likh kar aage badho. Sirf bacha hua code do." }] }
      ];
      var contUp = await fetch(url, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          systemInstruction: { parts: [{ text: sysText }] },
          contents: contContents,
          generationConfig: { temperature: 0.7, maxOutputTokens: 4096 }
        }),
        signal: AbortSignal.timeout(FETCH_TIMEOUT_MS)
      });
      if (contUp && contUp.ok) {
        var contData = null;
        try { contData = await contUp.json(); } catch (e) { contData = null; }
        var contReply = "";
        try {
          var cparts = contData && contData.candidates && contData.candidates[0] && contData.candidates[0].content && contData.candidates[0].content.parts;
          if (Array.isArray(cparts)) {
            contReply = cparts.map(function (p) { return p && typeof p.text === "string" ? p.text : ""; }).join("").trim();
          }
        } catch (e) { contReply = ""; }
        if (contReply) {
          var mm = contReply.match(/^\s*(===(HTML|CSS|JS)===)/);
          if (mm && reply.indexOf(mm[1]) >= 0) {
            contReply = contReply.replace(/^\s*===(HTML|CSS|JS)===\s*/, "");
          }
          reply = reply + "\n" + contReply;
          try { finishReason = (contData && contData.candidates && contData.candidates[0] && contData.candidates[0].finishReason) || finishReason; } catch (e) {}
        }
      }
    } catch (e) { /* continuation fail ho to partial reply hi rahega; neeche completeness check pakdega */ }
  }
  // Website: sections parse karo; HTML na mile to saaf Hinglish error.
  if (app === "website") {
    var wHtml = webPart(reply, "===HTML===", "===CSS===");
    var wCss = webPart(reply, "===CSS===", "===JS===");
    var wJs = webPart(reply, "===JS===", null);
    if (wHtml === null || wCss === null || wJs === null) {
      return json(res, 502, { error: "Website ka jawab samajh nahi aaya. Dobara bhejo." });
    }
    if (finishReason === "MAX_TOKENS") {
      return json(res, 502, { error: "Website ka code poora nahi ban paya (bahut lamba tha, beech mein kat gaya). Chhota/simpler website banao ya dobara try karo." });
    }
    return json(res, 200, { ok: true, reply: reply, website: { html: wHtml, css: wCss || "", js: wJs || "" } });
  }
  return json(res, 200, { reply: reply });
};
